    {
      "keystrokes": "convert /app/frames/sample_60.png -resize 200% -colorspace Gray -negate -threshold 50% /app/frames/sample_60_ocr.png && tesseract /app/frames/sample_60_ocr.png stdout 2>/dev/null | head -40\n",
      "duration": 1.0
    }
  ],
